mapper.select:
SELECT
a.*,
su.nickname AS leaderName,
bu.nickname AS bindUserName,
COUNT(s.id) AS stationCount  
FROM area_info a
LEFT JOIN station_user su ON a.user_id = su.id AND su.deleted = 0
LEFT JOIN station_user bu ON a.bind_user_id = bu.id AND bu.deleted = 0  
LEFT JOIN station_info s ON a.id = s.area_id AND s.deleted = 0  
WHERE a.deleted = 0


    AND a.id = #{pageReqVO.id}


    AND a.user_id = #{pageReqVO.userId}


    AND su.nickname LIKE CONCAT('%', #{pageReqVO.leaderName}, '%')


    AND a.area_no LIKE CONCAT('%', #{pageReqVO.areaNo}, '%')


    AND a.name LIKE CONCAT('%', #{pageReqVO.name}, '%')


    AND a.district LIKE CONCAT('%', #{pageReqVO.district}, '%')


    AND a.phone LIKE CONCAT('%', #{pageReqVO.phone}, '%')


    AND a.bind_user_id = #{pageReqVO.bindUserId}


    AND a.status = #{pageReqVO.status}


    AND a.remark = #{pageReqVO.remark}


    AND a.reserve1 = #{pageReqVO.reserve1}


    AND a.reserve2 = #{pageReqVO.reserve2}


    AND a.create_time BETWEEN #{pageReqVO.createTime[0]} AND #{pageReqVO.createTime[1]}



GROUP BY a.id



    HAVING COUNT(s.id) = #{pageReqVO.stationCount}


ORDER BY a.id DESC
